   124|async function tick(): Promise<void> {
   125|  // ─── Orphan-task recovery ──────────────────────────────────────────
   126|  // If the worker restarts mid-loop (e.g. Render redeploy), a task can be
   127|  // left in RUNNING/TESTING with a stale heartbeat. Requeue any senior-dev
   128|  // task whose heartbeat is older than TASK_CLAIM_TIMEOUT_MS so it gets
   129|  // re-picked instead of sitting orphaned forever (root cause of the
   130|  // 20f65308 task stuck in TESTING for 26+ min across a restart).
   131|  try {
   132|    await recoverOrphanedTasks();
   133|  } catch (error) {
   134|    console.log('[IVX-SENIOR-DEV-01] Orphan recovery error (non-fatal):', error instanceof Error ? error.message : 'unknown');
   135|  }
   136|
   137|  const tasks = await listTasks(50);
   138|  const candidates = tasks.filter((t) => {
   139|    // Mark senior_dev tasks via trace_id (always "senior-dev-..." from the
   140|    // submit endpoint) because the task_type column is only created by the
   141|    // self-bootstrap DDL, which requires SUPABASE_ACCESS_TOKEN and may not have
   142|    // run yet. trace_id is in the original CREATE TABLE and is always present,
   143|    // so it is the reliable marker. task_type is checked too as a fallback.
   144|    const isSeniorDev = (t.task_type === 'senior_dev')
   145|      || (typeof t.trace_id === 'string' && t.trace_id.startsWith('senior-dev-'));
   146|    if (!isSeniorDev) return false;
   147|    if (t.status !== 'QUEUED' && t.status !== 'RETRYING') return false;
   148|    if (t.assigned_worker_id && t.assigned_worker_id !== IVX_SENIOR_DEV_WORKER_ID) return false;
   149|    return true;
   150|  });
   151|
   152|  if (candidates.length === 0) return;
   153|
   154|  const task = candidates.sort((a, b) => new Date(a.created_at).getTime() - new Date(b.created_at).getTime())[0];
   155|  if (!task) return;
   156|
   157|  const claimed = await claimTask(task.id);
   158|  if (!claimed) return;
   159|
   160|  state.currentTaskId = task.id;
   161|  state.runCount += 1;
   162|
   163|  try {
   164|    await executeSeniorDevTask(claimed);
   165|  } catch (error) {
   166|    state.errorCount += 1;
   167|    console.log('[IVX-SENIOR-DEV-01] executeSeniorDevTask error:', error instanceof Error ? error.message : 'unknown');
   168|    await failTask(task.id, error instanceof Error ? error.message : 'unknown');
   169|  } finally {
   170|    state.currentTaskId = null;
   171|    state.currentPhase = null;
   172|  }
   173|}
