   213|async function claimTask(taskId: string): Promise<IVXOwnerAITaskRow | null> {
   214|  const now = new Date().toISOString();
   215|  // The submit endpoint pre-assigns assigned_worker_id='IVX-SENIOR-DEV-01' so the
   216|  // task is already bound to this worker. The optimistic claim must therefore
   217|  // accept rows where assigned_worker_id IS NULL (unassigned) OR already equals
   218|  // IVX-SENIOR-DEV-01 (pre-assigned to us). Using PostgREST or= syntax.
   219|  const filter = `&status=in.(QUEUED,RETRYING)&or=(assigned_worker_id.is.null,assigned_worker_id.eq.${encodeURIComponent(IVX_SENIOR_DEV_WORKER_ID)})`;
   220|  const patched = await patchTask(taskId, {
   221|    status: 'RUNNING',
   222|    checkpoint: `CLAIMED by ${IVX_SENIOR_DEV_WORKER_ID}`,
   223|    assigned_worker_id: IVX_SENIOR_DEV_WORKER_ID,
   224|    heartbeat_at: now,
   225|    checkpoint_history: appendCheckpoint(null, `CLAIMED by ${IVX_SENIOR_DEV_WORKER_ID} at ${now}`),
   226|  }, filter);
   227|  return patched;
