   242|async function executeSeniorDevTask(task: IVXOwnerAITaskRow): Promise<void> {
   243|  const run = await writeProofLedger({
   244|    taskId: task.id,
   245|    workerId: IVX_SENIOR_DEV_WORKER_ID,
