   247|    repository: process.env.GITHUB_REPO_URL ?? undefined,
   248|  });
   249|  if (!run) {
   250|    // Proof ledger write failed (table missing / Supabase unreachable). This is
   251|    // a hard failure for a senior_dev task — without a ledger there is no honest
   252|    // evidence trail. Do NOT fall through to a hollow VERIFIED. Fail loudly.
   253|    throw new Error('Failed to create proof ledger run record (ivx_senior_dev_worker_runs table unreachable — check SUPABASE_URL + SUPABASE_SERVICE_ROLE_KEY + ensureSeniorDevTables bootstrap).');
   254|  }
   255|  const runId = run.id;
